CREATE FUNCTION public.copilot_member(_deal text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_approved(auth.uid()) AND EXISTS(SELECT 1 FROM public.deals WHERE id=_deal) AND public.can_access_deal(_deal) $$;
CREATE FUNCTION public.copilot_editor(_deal text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.copilot_member(_deal) AND public.is_admin(auth.uid()) $$;
CREATE TABLE public.copilot_threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deal_id text NOT NULL UNIQUE REFERENCES public.deals(id) ON DELETE CASCADE, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.copilot_threads TO authenticated; GRANT ALL ON public.copilot_threads TO service_role;
ALTER TABLE public.copilot_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY copilot_threads_read ON public.copilot_threads FOR SELECT TO authenticated USING(public.copilot_member(deal_id));
CREATE TABLE public.copilot_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.copilot_threads(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant')), body text NOT NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.copilot_messages TO authenticated; GRANT ALL ON public.copilot_messages TO service_role;
ALTER TABLE public.copilot_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY copilot_messages_read ON public.copilot_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.copilot_threads t WHERE t.id=thread_id AND public.copilot_member(t.deal_id)));
CREATE TABLE public.copilot_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.copilot_threads(id) ON DELETE CASCADE, document_id uuid NOT NULL REFERENCES public.deal_documents(id) ON DELETE CASCADE, content_hash text NOT NULL, extracted_text text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,content_hash));
GRANT SELECT ON public.copilot_documents TO authenticated; GRANT ALL ON public.copilot_documents TO service_role;
ALTER TABLE public.copilot_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY copilot_documents_read ON public.copilot_documents FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.copilot_threads t WHERE t.id=thread_id AND public.copilot_member(t.deal_id)));
CREATE TABLE public.copilot_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.copilot_threads(id) ON DELETE CASCADE, document_id uuid REFERENCES public.copilot_documents(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('document','syndicate')), revision text NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','completed','failed','paused','superseded')), baseline jsonb NOT NULL DEFAULT '{}'::jsonb, evidence_text text NOT NULL DEFAULT '', report jsonb, error text, lease_token uuid, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(thread_id,kind,revision));
GRANT SELECT ON public.copilot_runs TO authenticated; GRANT ALL ON public.copilot_runs TO service_role;
ALTER TABLE public.copilot_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY copilot_runs_read ON public.copilot_runs FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.copilot_threads t WHERE t.id=thread_id AND public.copilot_member(t.deal_id)));
CREATE UNIQUE INDEX copilot_single_flight ON public.copilot_runs(thread_id) WHERE status='processing';
CREATE TABLE public.copilot_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.copilot_threads(id) ON DELETE CASCADE, run_id uuid REFERENCES public.copilot_runs(id), field text NOT NULL CHECK(field IN ('issuer','currency','size','coupon','maturity','isin','governingLaw')), before_value text NOT NULL, after_value text NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_by uuid, decided_by uuid, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
GRANT SELECT ON public.copilot_changes TO authenticated; GRANT ALL ON public.copilot_changes TO service_role;
ALTER TABLE public.copilot_changes ENABLE ROW LEVEL SECURITY;
CREATE POLICY copilot_changes_read ON public.copilot_changes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.copilot_threads t WHERE t.id=thread_id AND public.copilot_member(t.deal_id)));
CREATE UNIQUE INDEX copilot_pending_dedup ON public.copilot_changes(thread_id,field,before_value,after_value) WHERE status='pending';
CREATE TABLE public.copilot_gateway_state(id text PRIMARY KEY, blocked boolean NOT NULL DEFAULT false, reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.copilot_gateway_state TO authenticated; GRANT ALL ON public.copilot_gateway_state TO service_role;
ALTER TABLE public.copilot_gateway_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY copilot_gateway_read ON public.copilot_gateway_state FOR SELECT TO authenticated USING(public.is_approved(auth.uid()));
CREATE FUNCTION public.copilot_context(_deal text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('issuer',coalesce((SELECT p->>'PartyName' FROM jsonb_array_elements(coalesce(d.bdt_state->'parties','[]')) p WHERE p->'Roles' ? 'ISSUER' LIMIT 1),''),'currency',coalesce(d.bdt_state->'f'->>'IssuanceDataGroup/Issuance/SpecifiedCurrency',''),'size',coalesce(d.bdt_state->'f'->>'IssuanceDataGroup/Issuance/TotalAggregateAmount/Value',''),'coupon',coalesce(d.bdt_state->'f'->>'IssuanceDataGroup/Product/InterestPayment/FixedRatePayment/InterestRate',''),'maturity',coalesce(d.bdt_state->'f'->>'IssuanceDataGroup/Product/Maturity/MaturityDate',''),'isin',coalesce((SELECT i->>'Value' FROM jsonb_array_elements(coalesce(d.bdt_state->'ids','[]')) i WHERE i->>'Type'='ISIN' LIMIT 1),''),'governingLaw',coalesce(d.bdt_state->'f'->>'IssuanceDataGroup/Issuance/GoverningLaw/CountryCode',''),'sourceText','') FROM public.deals d WHERE d.id=_deal $$;
REVOKE ALL ON FUNCTION public.copilot_context(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.copilot_context(text) TO service_role;
CREATE FUNCTION public.copilot_open(_deal text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NOT public.copilot_member(_deal) THEN RAISE EXCEPTION 'Deal membership required'; END IF; INSERT INTO public.copilot_threads(deal_id,created_by) VALUES(_deal,auth.uid()) ON CONFLICT(deal_id) DO NOTHING; SELECT id INTO tid FROM public.copilot_threads WHERE deal_id=_deal; RETURN tid; END $$;
REVOKE ALL ON FUNCTION public.copilot_open(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.copilot_open(text) TO authenticated;
CREATE FUNCTION public.copilot_enqueue(_thread uuid,_document uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.deals; rev text; BEGIN SELECT x.* INTO d FROM public.deals x JOIN public.copilot_threads t ON t.deal_id=x.id WHERE t.id=_thread; rev:=md5(coalesce(d.bdt_state,'{}')::text)||coalesce(_document::text,''); INSERT INTO public.copilot_runs(thread_id,kind,revision,baseline,document_id) VALUES(_thread,'syndicate',rev,public.copilot_context(d.id),_document) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.copilot_enqueue(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.copilot_enqueue(uuid,uuid) TO service_role;
CREATE FUNCTION public.copilot_on_term_save() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NEW.bdt_state IS DISTINCT FROM OLD.bdt_state THEN SELECT id INTO tid FROM public.copilot_threads WHERE deal_id=NEW.id; IF tid IS NOT NULL THEN PERFORM public.copilot_enqueue(tid); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER copilot_term_save AFTER UPDATE OF bdt_state ON public.deals FOR EACH ROW EXECUTE FUNCTION public.copilot_on_term_save();
CREATE FUNCTION public.copilot_register_document(_thread uuid,_document uuid,_text text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE did uuid; deal text; BEGIN SELECT deal_id INTO deal FROM public.copilot_threads WHERE id=_thread; IF deal IS NULL OR NOT public.copilot_member(deal) THEN RAISE EXCEPTION 'Deal membership required'; END IF; IF length(trim(_text))=0 OR length(_text)>60000 THEN RAISE EXCEPTION 'Readable document text must be within 60000 characters'; END IF; IF NOT EXISTS(SELECT 1 FROM public.deal_documents WHERE id=_document AND deal_id=deal) THEN RAISE EXCEPTION 'Document does not belong to this deal'; END IF; INSERT INTO public.copilot_documents(thread_id,document_id,content_hash,extracted_text,created_by) VALUES(_thread,_document,md5(_text),_text,auth.uid()) ON CONFLICT(thread_id,content_hash) DO NOTHING; SELECT id INTO did FROM public.copilot_documents WHERE thread_id=_thread AND content_hash=md5(_text); INSERT INTO public.copilot_runs(thread_id,kind,document_id,revision) VALUES(_thread,'document',did,did::text) ON CONFLICT DO NOTHING; RETURN did; END $$;
REVOKE ALL ON FUNCTION public.copilot_register_document(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.copilot_register_document(uuid,uuid,text) TO authenticated;
CREATE FUNCTION public.copilot_propose(_thread uuid,_field text,_before text,_after text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE deal text; BEGIN SELECT deal_id INTO deal FROM public.copilot_threads WHERE id=_thread; IF deal IS NULL OR NOT public.copilot_member(deal) THEN RAISE EXCEPTION 'Deal membership required'; END IF; PERFORM 1 FROM public.deals WHERE id=deal FOR UPDATE; IF _field NOT IN ('issuer','currency','size','coupon','maturity','isin','governingLaw') OR length(trim(_after))=0 OR length(_after)>2000 OR length(trim(_reason))=0 OR length(_reason)>4000 THEN RAISE EXCEPTION 'Invalid proposal'; END IF; IF public.copilot_context(deal)->>_field IS DISTINCT FROM _before THEN RAISE EXCEPTION 'Deal changed; refresh the proposal'; END IF; INSERT INTO public.copilot_changes(thread_id,field,before_value,after_value,reason,created_by) VALUES(_thread,_field,_before,_after,_reason,auth.uid()) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.copilot_propose(uuid,text,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.copilot_propose(uuid,text,text,text,text) TO authenticated;
CREATE FUNCTION public.copilot_claim(_run uuid,_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.copilot_runs; deal text; BEGIN SELECT * INTO r FROM public.copilot_runs WHERE id=_run; IF r.id IS NULL THEN RETURN false; END IF; PERFORM 1 FROM public.copilot_threads WHERE id=r.thread_id FOR UPDATE; UPDATE public.copilot_runs SET status='queued',lease_token=NULL,lease_until=NULL WHERE thread_id=r.thread_id AND status='processing' AND lease_until<now(); IF EXISTS(SELECT 1 FROM public.copilot_runs WHERE thread_id=r.thread_id AND status='processing') THEN RETURN false; END IF; SELECT deal_id INTO deal FROM public.copilot_threads WHERE id=r.thread_id; IF r.kind='syndicate' AND r.baseline IS DISTINCT FROM public.copilot_context(deal) THEN UPDATE public.copilot_runs SET status='superseded' WHERE id=_run; RETURN false; END IF; UPDATE public.copilot_runs SET status='processing',lease_token=_token,lease_until=now()+interval '10 minutes' WHERE id=_run AND status='queued'; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.copilot_claim(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.copilot_claim(uuid,uuid) TO service_role;
CREATE FUNCTION public.copilot_complete(_run uuid,_token uuid,_report jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.copilot_runs; deal text; ctx jsonb; term jsonb; differences jsonb:='[]'; doc public.copilot_documents; evidence text; before text; BEGIN SELECT deal_id INTO deal FROM public.copilot_threads t JOIN public.copilot_runs x ON x.thread_id=t.id WHERE x.id=_run; PERFORM 1 FROM public.deals WHERE id=deal FOR UPDATE; SELECT * INTO r FROM public.copilot_runs WHERE id=_run FOR UPDATE; IF r.status<>'processing' OR r.lease_token IS DISTINCT FROM _token OR r.lease_until<now() THEN RETURN false; END IF; ctx:=public.copilot_context(deal); IF r.kind='syndicate' AND ctx IS DISTINCT FROM r.baseline THEN UPDATE public.copilot_runs SET status='superseded',lease_token=NULL,lease_until=NULL WHERE id=_run; RETURN false; END IF; IF r.kind='document' THEN SELECT * INTO doc FROM public.copilot_documents WHERE id=r.document_id; evidence:=doc.extracted_text; ELSE evidence:=r.evidence_text; END IF; IF jsonb_typeof(_report->'terms')<>'array' OR length(trim(_report->>'summary'))=0 THEN RAISE EXCEPTION 'Invalid review'; END IF; FOR term IN SELECT value FROM jsonb_array_elements(_report->'terms') LOOP IF term->>'field' NOT IN ('issuer','currency','size','coupon','maturity','isin','governingLaw') OR length(trim(term->>'value'))=0 OR length(term->>'value')>2000 OR length(trim(term->>'quote'))=0 OR position(term->>'quote' IN evidence)=0 OR (SELECT count(*) FROM jsonb_array_elements(_report->'terms') q WHERE q->>'field'=term->>'field')<>1 THEN RAISE EXCEPTION 'Unsupported or ambiguous source evidence'; END IF; before:=coalesce(ctx->>(term->>'field'),''); IF before<>term->>'value' THEN differences:=differences||jsonb_build_array(term||jsonb_build_object('before',before,'after',term->>'value')); INSERT INTO public.copilot_changes(thread_id,run_id,field,before_value,after_value,reason) VALUES(r.thread_id,r.id,term->>'field',before,term->>'value',left(coalesce(term->>'location','')||': '||(term->>'quote'),4000)) ON CONFLICT DO NOTHING; END IF; END LOOP; _report:=_report||jsonb_build_object('differences',differences,'comparison',jsonb_build_object('mode','live','comparedAt',now(),'termSheetUpdatedAt',(SELECT updated_at FROM public.deals WHERE id=deal))); UPDATE public.copilot_runs SET status='completed',baseline=ctx,report=_report,completed_at=now(),lease_token=NULL,lease_until=NULL WHERE id=_run; IF r.kind='document' THEN PERFORM public.copilot_enqueue(r.thread_id,r.document_id); END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.copilot_complete(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.copilot_complete(uuid,uuid,jsonb) TO service_role;
CREATE FUNCTION public.copilot_decide(_change uuid,_approve boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.copilot_changes; d public.deals; deal text; st jsonb; path text; pos integer; status text; BEGIN SELECT t.deal_id INTO deal FROM public.copilot_changes x JOIN public.copilot_threads t ON t.id=x.thread_id WHERE x.id=_change; IF deal IS NULL OR NOT public.copilot_editor(deal) THEN RAISE EXCEPTION 'Term-edit rights required'; END IF; SELECT * INTO d FROM public.deals WHERE id=deal FOR UPDATE; SELECT * INTO c FROM public.copilot_changes WHERE id=_change FOR UPDATE; IF c.status<>'pending' THEN RAISE EXCEPTION 'Change already decided'; END IF; IF _approve THEN IF public.copilot_context(deal)->>c.field IS DISTINCT FROM c.before_value THEN RAISE EXCEPTION 'Deal changed; request a new proposal'; END IF; st:=d.bdt_state; IF st IS NULL OR st->'f' IS NULL THEN RAISE EXCEPTION 'Save the term sheet before approving changes'; END IF; path:=CASE c.field WHEN 'currency' THEN 'IssuanceDataGroup/Issuance/SpecifiedCurrency' WHEN 'size' THEN 'IssuanceDataGroup/Issuance/TotalAggregateAmount/Value' WHEN 'coupon' THEN 'IssuanceDataGroup/Product/InterestPayment/FixedRatePayment/InterestRate' WHEN 'maturity' THEN 'IssuanceDataGroup/Product/Maturity/MaturityDate' WHEN 'governingLaw' THEN 'IssuanceDataGroup/Issuance/GoverningLaw/CountryCode' ELSE NULL END; IF path IS NOT NULL THEN st:=jsonb_set(st,ARRAY['f',path],to_jsonb(c.after_value),true); ELSIF c.field='issuer' THEN SELECT ord::integer-1 INTO pos FROM jsonb_array_elements(coalesce(st->'parties','[]')) WITH ORDINALITY x(v,ord) WHERE v->'Roles' ? 'ISSUER' LIMIT 1; IF pos IS NULL THEN st:=jsonb_set(st,'{parties}',coalesce(st->'parties','[]')||jsonb_build_array(jsonb_build_object('PartyName',c.after_value,'LEIIdentifier','','Roles',jsonb_build_array('ISSUER'),'Ratings','[]'::jsonb))); ELSE st:=jsonb_set(st,ARRAY['parties',pos::text,'PartyName'],to_jsonb(c.after_value)); END IF; st:=jsonb_set(st,'{deal}',to_jsonb(c.after_value)); ELSE SELECT ord::integer-1 INTO pos FROM jsonb_array_elements(coalesce(st->'ids','[]')) WITH ORDINALITY x(v,ord) WHERE v->>'Type'='ISIN' LIMIT 1; IF pos IS NULL THEN st:=jsonb_set(st,'{ids}',coalesce(st->'ids','[]')||jsonb_build_array(jsonb_build_object('Type','ISIN','Value',c.after_value))); ELSE st:=jsonb_set(st,ARRAY['ids',pos::text,'Value'],to_jsonb(c.after_value)); END IF; END IF; UPDATE public.deals SET bdt_state=st,issuer_name=CASE WHEN c.field='issuer' THEN c.after_value ELSE issuer_name END,currency=CASE WHEN c.field='currency' THEN c.after_value ELSE currency END,size=CASE WHEN c.field='size' THEN c.after_value ELSE size END,coupon=CASE WHEN c.field='coupon' THEN c.after_value ELSE coupon END,maturity_date=CASE WHEN c.field='maturity' THEN c.after_value ELSE maturity_date END,isin=CASE WHEN c.field='isin' THEN c.after_value ELSE isin END,governing_law=CASE WHEN c.field='governingLaw' THEN CASE c.after_value WHEN 'GB' THEN 'ENGLISH_LAW' WHEN 'US' THEN 'NEW_YORK_LAW' WHEN 'FR' THEN 'FRENCH_LAW' WHEN 'DE' THEN 'GERMAN_LAW' WHEN 'CH' THEN 'SWISS_LAW' ELSE '' END ELSE governing_law END WHERE id=deal; END IF; status:=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END; UPDATE public.copilot_changes SET status=copilot_decide.status,decided_by=auth.uid(),decided_at=now() WHERE id=_change; INSERT INTO public.audit_log(id,action,entity_type,entity_id,user_id,timestamp,details) VALUES(gen_random_uuid()::text,'copilot_'||status,'deal',deal,auth.uid()::text,now(),jsonb_build_object('changeId',_change,'field',c.field,'before',c.before_value,'after',c.after_value)::text); RETURN status; END $$;
REVOKE ALL ON FUNCTION public.copilot_decide(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.copilot_decide(uuid,boolean) TO authenticated;
CREATE POLICY copilot_members_upload_files ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='deal-documents' AND public.copilot_member((storage.foldername(name))[1]));
CREATE POLICY copilot_members_add_documents ON public.deal_documents FOR INSERT TO authenticated WITH CHECK(public.copilot_member(deal_id) AND uploaded_by=auth.uid());